/* From Uiverse.io by Ali-Tahmazi99 - Tags: hamburger */
.__UIV_SCOPE__ input[type = "checkbox"] {
  -webkit-appearance: none;
  display: none;
  visibility: hidden;
}

.__UIV_SCOPE__ .bar {
  display: block;
  position: relative;
  cursor: pointer;
  width: 50px;
  height: 40px;
}

.__UIV_SCOPE__ .bar span {
  position: absolute;
  width: 45px;
  height: 7px;
  background: #f1faee;
  border-radius: 100px;
  display: inline-block;
  transition: 0.3s ease;
  left: 0;
}

.__UIV_SCOPE__ .bar span.top {
  top: 0;
}

.__UIV_SCOPE__ .bar span.middle {
  top: 17px;
}

.__UIV_SCOPE__ .bar span.bottom {
  bottom: 0;
}

.__UIV_SCOPE__ input[type]:checked ~ span.top {
  transform: rotate(45deg);
  transform-origin: top left;
  width: 48px;
  left: 5px;
}

.__UIV_SCOPE__ input[type]:checked ~ span.bottom {
  transform: rotate(-45deg);
  transform-origin: top left;
  width: 48px;
  bottom: -1px;
  box-shadow: 0 0 10px #495057;
}

.__UIV_SCOPE__ input[type]:checked ~ span.middle {
  transform: translateX(-20px);
  opacity: 0;
}
